 private PlayerEntity target;private final Map<BlockPos,BlockState> wall=new HashMap<>();private void check(boolean b,String reason){if(!b)throw new AssertionError(reason);}private void click(MinecraftClient c,String name){Screen s=WorkspaceScreen.actual(c.currentScreen);var button=s.children().stream().filter(e->e instanceof ClickableWidget w&&w.getMessage().getString().startsWith(name)).map(e->(ClickableWidget)e).findFirst().orElseThrow(()->new AssertionError(name));double x=button.getX()+button.getWidth()/2.,y=button.getY()+button.getHeight()/2.;if(c.currentScreen instanceof WorkspaceScreen w){x=w.screenX(x);y=w.screenY(y);}var event=new Click(x,y,new MouseInput(0,0));check(c.currentScreen.mouseClicked(event,false),"Click rejected "+name);c.currentScreen.mouseReleased(event);}
